import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        uint beforeBalance = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(address(this), value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBalance = address(c).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        assertTrue(reverted ? (afterBalance == beforeBalance && afterDeposits == beforeDeposits) : (afterBalance + value == beforeBalance && afterDeposits == beforeDeposits));
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
